    int i, max_len = 0;
    for (i = 0; i < num_inputs; i++) {
        int len = strlen(inputs[i]);
        if (len > max_len) {
            max_len = len;
        }
    }

    // Pad inputs with spaces to make them same length
    for (i = 0; i < num_inputs; i++) {
        int len = strlen(inputs[i]);
        int pad = max_len - len;
        if (pad > 0) {
            char *pad_str = malloc(pad * sizeof(*pad_str));
            memset(pad_str,'', pad);
            inputs[i] = realloc(inputs[i], (len + pad) * sizeof(*inputs[i]));
            strncat(inputs[i], pad_str, pad);
            free(pad_str);
        }
    }

    // Print padded inputs
    for (i = 0; i < num_inputs; i++) {
        printf("%s\n", inputs[i]);
    }

    return 0;
}
